46	/**
47	 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
48	 * their claims that counts (OPEN or SETTLED) to the figure it has now, unbinds the rest, and moves
49	 * the person's statement count, last due-total and date (the sheet's today) on.
50	 *
51	 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
52	 * the person's grade's rate in force on its date (n/a without one). The due-total adds up the counting
53	 * claims' figures, skipping n/a; it is n/a when the grade has no rate on today and no counting claim
54	 * keeps a fixed figure.
55	 */
56	public class TakeStatement {
57	    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
58	            SheetClock clock, Out<Statement> statementOut) {
59	        String sheetId = person.getSheetId();
60	        LocalDate today = clock.today(sheetId);
61	        List<Rate> rates = rateRepository.findBySheet(sheetId);
62	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
63	        boolean fixed = false;
64	        int counted = 0;
65	        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
66	            boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
67	            if (!counts) {
68	                claim.setStated(false);
69	                claim.setStatedDue(null);
70	            } else {
71	                BigDecimal figure = figure(claim, person, rates);
72	                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
73	                if (figure != null) sum = sum.add(figure);
74	                claim.setStated(true);
75	                claim.setStatedDue(figure);
76	                counted++;
77	            }
78	            claims.save(claim);
79	        }
80	        BigDecimal dueTotal = Rate.inForce(rates, person.getGrade(), today).isEmpty() && !fixed ? null : sum;
81	        person.setStatementCount(person.getStatementCount() + 1);
82	        person.setStatedTotal(dueTotal);
83	        person.setStatementDate(today);
84	        people.saveStatement(person);
85	        statementOut.set(new Statement(dueTotal, counted));
86	    }
87	
88	    /** amount × pct / 100, rounded half to even to two decimals, unless already fixed; null when n/a. */
89	    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates) {
90	        if (claim.getSettledDue() != null) return claim.getSettledDue();
91	        if (claim.isStated()) return claim.getStatedDue();
92	        return Rate.inForce(rates, person.getGrade(), claim.getDate())
93	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
94	                .orElse(null);
95	    }
