134	/**
135	 * The sheet's figures as the screen shows them: each person's claimed and due-total, in the order
136	 * they were added, and the sheet's claimed-total and due-total.
137	 *
138	 * Only OPEN and SETTLED claims count. A claim's figure is its settled due, else the figure a statement
139	 * bound it to, else its live due at the person's grade's rate in force on its date (n/a without one).
140	 * A person's due-total adds up their counting claims' figures, skipping n/a; it is n/a when the grade
141	 * has no rate on the sheet's today and no counting claim keeps a fixed figure. The sheet's due-total
142	 * adds up the people's due-totals, skipping n/a.
143	 */
144	@Service
145	public class Rollup {
146	
147	    static final String NA = "n/a";
148	
149	    /** One person's figures, as text with two decimals (due-total may be n/a). */
150	    public record Figures(String name, String claimed, String dueTotal) {
151	        boolean sameAs(Figures other) {
152	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
153	        }
154	    }
155	
156	    /** The sheet's figures at one moment: people by id, in the order they were added, and the totals. */
157	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
158	        boolean sameTotals(Snapshot other) {
159	            return claimedTotal.equals(other.claimedTotal) && dueTotal.equals(other.dueTotal);
160	        }
161	    }
162	
163	    private final PersonRepository people;
164	    private final ClaimRepository claims;
165	    private final RateRepository rates;
166	    private final SheetClock clock;
167	
168	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetClock clock) {
169	        this.people = people;
170	        this.claims = claims;
171	        this.rates = rates;
172	        this.clock = clock;
173	    }
174	
175	    public Snapshot take(String sheetId) {
176	        LocalDate today = clock.today(sheetId);
177	        List<Rate> sheetRates = rates.findBySheet(sheetId);
178	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
179	        Map<Long, Figures> figures = new LinkedHashMap<>();
180	        BigDecimal claimedTotal = zero();
181	        BigDecimal dueTotal = zero();
182	        for (Person person : people.findBySheet(sheetId)) {
183	            BigDecimal claimed = zero();
184	            BigDecimal due = zero();
185	            boolean fixed = false;
186	            for (Claim claim : sheetClaims) {
187	                if (claim.getPersonId() != person.getId()) continue;
188	                if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.SETTLED) continue;
189	                claimed = claimed.add(claim.getAmount());
190	                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
191	                BigDecimal figure = figure(claim, person, sheetRates);
192	                if (figure != null) due = due.add(figure);
193	            }
194	            boolean na = Rate.inForce(sheetRates, person.getGrade(), today).isEmpty() && !fixed;
195	            claimedTotal = claimedTotal.add(claimed);
196	            if (!na) dueTotal = dueTotal.add(due);
197	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), na ? NA : text(due)));
198	        }
199	        return new Snapshot(figures, text(claimedTotal), text(dueTotal));
200	    }
201	
202	    /** The ROLLUP lines for each person whose figures moved since {@code before} (a new person counts
203	     *  as moved), then a TOTALS line when the sheet's totals moved. */
204	    public List<String> changes(String sheetId, String user, Snapshot before, Snapshot after) {
205	        String prefix = " sheet=" + sheetId + " by=" + user;
206	        List<String> lines = new ArrayList<>();
207	        after.people().forEach((id, now) -> {
208	            if (!now.sameAs(before.people().get(id))) {
209	                lines.add("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
210	                        + " due-total=" + now.dueTotal());
211	            }
212	        });
213	        if (!after.sameTotals(before)) {
214	            lines.add("TOTALS" + prefix + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
215	        }
216	        return lines;
217	    }
218	
219	    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates) {
220	        if (claim.getSettledDue() != null) return claim.getSettledDue();
221	        if (claim.isStated()) return claim.getStatedDue();
222	        return Rate.inForce(rates, person.getGrade(), claim.getDate())
223	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
224	                .orElse(null);
225	    }
226	
227	    private static BigDecimal zero() {
228	        return BigDecimal.ZERO.setScale(2);
229	    }
230	
231	    private static String text(BigDecimal value) {
232	        return Objects.requireNonNull(value).setScale(2, RoundingMode.HALF_EVEN).toPlainString();
233	    }
234	}
