252	import java.nio.charset.StandardCharsets;
253	import java.nio.file.Files;
254	import java.nio.file.Path;
255	import java.nio.file.StandardOpenOption;
256	import org.springframework.beans.factory.annotation.Value;
257	import org.springframework.stereotype.Service;
258	
259	/**
260	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
261	 * so tests can assert side-effects by reading that file — the second test-assertion channel
262	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
263	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
264	 *
265	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
266	 * SYNC) so a test reads the record immediately.
267	 */
268	@Service
269	public class Audit {
270	
271	    private final Path file;
272	
273	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
274	        this.file = Path.of(path);
275	    }
276	
277	    /** Append one audit record. Tests assert the exact line(s) in the file. */
278	    public synchronized void record(String entry) {
279	        try {
280	            Path parent = file.toAbsolutePath().getParent();
281	            if (parent != null) {
282	                Files.createDirectories(parent);
283	            }
284	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
285	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
286	        } catch (IOException e) {
287	            throw new UncheckedIOException(e);
288	        }
289	    }
290	
291	    /** Remove the audit file. */
292	    public synchronized void clear() {
293	        try {
294	            Files.deleteIfExists(file);
295	        } catch (IOException e) {
296	            throw new UncheckedIOException(e);
297	        }
298	    }
299	}
