490	            throw new InvalidClaimStatusException(
491	                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
492	        }
493	        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
494	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
495	        }
